rnd = random.Random(4421)
mcqs = []
for item in M:
    if item[0] == "fixed":
        _, qs, opts, ans, exp = item
        mcqs.append({"q": qs, "options": list(opts), "answer": ans, "exp": exp})
    else:
        _, qs, opts, exp = item
        correct = opts[0]
        o = list(opts)
        rnd.shuffle(o)
        mcqs.append({"q": qs, "options": o, "answer": o.index(correct), "exp": exp})

